def seg_fill(gi,go,name):
    gi=G[name+' input']; go=G[name+' output']
    H,W=len(gi),len(gi[0]); bg=gi[0][0]
    pos=[(r,c) for r in range(H) for c in range(W) if gi[r][c]!=bg]
